// ── Content generator ──
function generateContent(title, tags) {
  const tag = tags[0] || "Technology";
  const sections = [
    `## Introduction\n\n${title} is a critical topic for modern software developers. In this comprehensive guide, we'll explore the key concepts, practical implementations, and best practices that you need to master.`,
    `## Key Concepts\n\nUnderstanding the fundamentals is essential before diving into implementation details. Let's break down the core concepts:\n\n- **Concept 1**: The foundation of the topic\n- **Concept 2**: How it integrates with existing systems\n- **Concept 3**: Performance and scalability considerations\n- **Concept 4**: Security implications and best practices`,
    `## Practical Implementation\n\nLet's look at a practical example:\n\n\`\`\`typescript\n// Example implementation\nfunction process(input: string): Result {\n  // Validate input\n  if (!input) throw new Error("Input required");\n  \n  // Process data\n  const result = transform(input);\n  \n  // Return formatted output\n  return format(result);\n}\n\`\`\`\n\nThis pattern demonstrates the core approach to implementing ${tag} solutions in production environments.`,
    `## Best Practices\n\n1. **Start simple** — don't over-engineer from the beginning\n2. **Test thoroughly** — automated tests catch regressions early\n3. **Monitor production** — observability is key to reliability\n4. **Document decisions** — future you will thank present you\n5. **Stay updated** — the ecosystem evolves rapidly`,
    `## Common Pitfalls\n\n| Pitfall | Impact | Solution |\n|---------|--------|----------|\n| Ignoring error handling | Production crashes | Always handle edge cases |\n| Premature optimization | Complexity without benefit | Profile first, then optimize |\n| Skipping tests | Regressions | Write tests alongside code |\n| Not monitoring | Blind spots in production | Implement observability early |`,
    `## Conclusion\n\n${title} is an essential skill for modern developers. By following the patterns and best practices outlined in this guide, you'll be well-equipped to implement robust, scalable solutions. Keep experimenting, stay curious, and continue building.`,
  ];
  return sections.join("\n\n");
}

// ── Generate all files ──
let count = 0;
for (const [year, month, day, title, description, tags] of BLOGS) {
  const slug = slugify(title);
  const date = dateStr(year, month, day);
  const content = generateContent(title, tags);
  
  const frontmatter = `---
title: "${title.replace(/"/g, '\\"')}"
date: "${date}"
description: "${description.replace(/"/g, '\\"')}"
tags: [${tags.map(t => `"${t}"`).join(", ")}]
published: true
author: "MinhVo"
---

${content}
`;
  
  const filePath = join(OUT, `${slug}.mdx`);
  writeFileSync(filePath, frontmatter, "utf-8");
  count++;
}

console.log(`✅ Generated ${count} blog posts in ${OUT}`);
